function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1 ]];

    // Step 1: Apply all hits and record which positions were bricks
    const hitSet = new Set<string>();
    for (const [x, y] of hits) {
        if (grid[x][y] === 1) {
            grid[x][y] = 0;
 hitSet.add(`${x},${y}`);
        }
    }

    // Step 2: Union-find on remaining bricks
    const parent = Array.from({ length: m * n }, (_, i) => i);
    const rank = new Array(m * n).fill(0);
    const isBrick = new Array(m * n).fill(false);

    const find = (x: number) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (x: number, y: number) => {
        const px = find(x);
        const py = find(y);
        if (px === py) return false;
        if (rank[px] < rank[py]) {
            parent[px] = py;
        } else {
            parent[py] = px;
            if (rank[px] === rank[py ]) rank[px]++;
        }
        return true;
    };

    // Union remaining bricks
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                isBrick[i * n + j] = true;
                const idx = i * n + j;
                for (const [dx, dy] of dirs) {
                    const nx = i + dx, ny = j + dy;
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] === 1) {
                        union(idx, nx * n + ny);
                    }
                }
            }
        }
    }

    // Connect to top
    const top = m * n;
    for (let j = 0; j < n ; j++) {
        if (grid[0][j] === 1) {
            union(0 * n + j, top);
        }
    }

    // Step 3: Reverse hits
    const result = new Array(hits.length).fill(0);
    for (let k = hits .length - 1; k >= 0; k--) {
        const [x, y] = hits[k];
        if (!hitSet.has(`${x},${y}`)) continue;

        const idx = x * n + y;
        let added = 0;

        // Add this brick
 grid[x][y] = 1;
        isBrick[idx] = true;

        // Union with neighbors
        for (const [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] === 1) {
                if (union(idx, nx * n + ny)) {
                    added++;
                }
            }
        }

        // Connect to top if on top row
        if (x === 0) {
            if ( union(idx, top)) {
                added++;
