function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const parent: number[] = new Array(m * n + 1);
    const sz: number[] = new Array(m * n + 1).fill(1);
    for (let i = 0; i <= m * n; i++) parent[i] = i;
    sz[roof] = 0;

    const find = (x: number): number => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (x: number, y: number): void => {
        let px = find(x);
        let py = find(y);
        if (px === py) return;
        if (sz[px] < sz[py]) {
            parent[px] = py;
            sz[py] += sz[px];
        } else {
            parent[py] = px;
            sz[px] += sz[py];
        }
    };

    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const index = (i: number, j: number) => i * n + j;

    for (const [r, c] of hits) {
        grid[r][c]--;
    }

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === 0) union(index(i, j), roof);
                for (const [di, dj] of dirs) {
                    const ni = i + di, nj = j + dj;
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1) {
                        union(index(i, j), index(ni, nj));
                    }
                }
            }
        }
    }

    const res: number[] = new Array(hits.length).fill(0);
    for (let k = hits.length - 1; k >= 0; k--) {
        const [r, c] = hits[k];
        grid[r][c]++;
        if (grid[r][c] !== 1) continue;
        const old = sz[find(roof)];
        const id = index(r, c);
        if (r === 0) union(id, roof);
        for (const [di, dj] of dirs) {
            const ni = r + di, nj = c + dj;
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] === 1) {
                union(id, index(ni, nj));
            }
        }
        const neu = sz[find(roof)];
        res[k] = Math.max(0, neu - old - 1);
    }
    return res;
}
