    n: number;
    tree: number[];
    constructor(n: number) {
        this.n = n;
        this.tree = new Array(n + 1).fill(0);
    }
    update(i: number, delta: number): void {
        for (; i <= this.n; i += i & -i) this.tree[i] += delta;
    }
    query(i: number): number {
        let s = 0;
        for (; i > 0; i -= i & -i) s += this.tree[i];
        return s;
    }
}

class MKAverage {
    private m: number;
    private k: number;
    private stream: number[];
    private cnt: Fenwick;
    private sumf: Fenwick;
    private static readonly MAXV = 100000;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.stream = [];
        this.cnt = new Fenwick(MKAverage.MAXV);
        this.sumf = new Fenwick(MKAverage.MAXV);
    }

    addElement(num: number): void {
        this.stream.push(num);
        this.cnt.update(num, 1);
        this.sumf.update(num, num);
        if (this.stream.length > this.m) {
            const out = this.stream[this.stream.length - this.m - 1];
            this.cnt.update(out, -1);
            this.sumf.update(out, -out);
        }
    }

    private smallestSum(kk: number): number {
        if (kk === 0) return 0;
        let low = 1, high = MKAverage.MAXV;
        while (low < high) {
            const mid = (low + high) >> 1;
            if (this.cnt.query(mid) >= kk) high = mid;
            else low = mid + 1;
        }
        const pos = low;
        const prevCnt = pos > 1 ? this.cnt.query(pos - 1) : 0;
        const prevSum = pos > 1 ? this.sumf.query(pos - 1) : 0;
        return prevSum + (kk - prevCnt) * pos;
    }

    calculateMKAverage(): number {
        if (this.stream.length < this.m) return -1;
        const s = this.smallestSum(this.m - this.k) - this.smallestSum(this.k);
        return Math.floor(s / (this.m - 2 * this.k));
    }
}
