    const m = grid.length;
    const n = grid[0].length;
    const maxK = Math.min(m, n);

    const isMagic = (r: number, c: number, k: number): boolean => {
        let sum = 0;
        for (let j = 0; j < k; j++) sum += grid[r][c + j];
        for (let i = 1; i < k; i++) {
            let s = 0;
            for (let j = 0; j < k; j++) s += grid[r + i][c + j];
            if (s !== sum) return false;
        }
        for (let j = 0; j < k; j++) {
            let s = 0;
            for (let i = 0; i < k; i++) s += grid[r + i][c + j];
            if (s !== sum) return false;
        }
        let d1 = 0;
        for (let i = 0; i < k; i++) d1 += grid[r + i][c + i];
        if (d1 !== sum) return false;
        let d2 = 0;
        for (let i = 0; i < k; i++) d2 += grid[r + i][c + k - 1 - i];
        if (d2 !== sum) return false;
        return true;
    };

    for (let k = maxK; k >= 1; k--) {
        for (let i = 0; i <= m - k; i++) {
            for (let j = 0; j <= n - k; j++) {
                if (isMagic(i, j, k)) return k;
            }
        }
    }
    return 1;
};
