    const m = nums.length;
    const memo: number[] = new Array(1 << m).fill(-1);
    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };
    const bitCount = (mask: number): number => {
        let count = 0;
        while (mask) {
            count += mask & 1;
            mask >>= 1;
        }
        return count;
    };
