    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + fruits[i][1];
    }

    // Now use 2 pointers to find max sum in [i..j] with cost <= k
    let i = left;
    for (let j = left; j <= right; j++) {
