    const n = target.length;
    const N = 1 << n;
    const dist = new Array(N).fill(-1);
    const counts: number[][] = stickers.map(s => {
        const cnt = new Array(26).fill(0);
        for (const c of s) cnt[c.charCodeAt(0) - 97]++;
        return cnt;
