    dist[full] = 0;
    const queue: number[] = [full];
    let qh = 0;
    while (qh < queue.length) {
        const mask = queue[qh++];
        if (mask === 0) return dist[mask];
        for (const sc of counts) {
            const cnt = sc.slice();
            let newmask = mask;
            for (let i = 0; i < n; i++) {
