```typescript
function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const a = Math.min(firstPlayer, secondPlayer);
    const b = Math.max(firstPlayer, secondPlayer);
    const memo = new Map<string, [number, number]>();

    const icalc = (m: number, x: number, y: number): [number, number] => {
        const key = `${m},${x},${y}`;
        if (memo.has(key)) return memo.get(key)!;
        if (x + y === m + 1) return [1,  1];
        const left = x - 1;
        const right = m - y;
        const mid = m - left - right - 2;
        const nextSize = Math.ceil(m / 2);
        let minR = Infinity;
        let maxR = 0;
        for (let l = 0; l <= left; l++) {
            for (let r = 0; r <= right; r++) {
                const m2 = l + r + mid + 2;
                if (m2 > nextSize) continue;
                const nextLeft = l;
                const nextRight = r;
                const nextMid = m2 - nextLeft - nextRight - 2;
                const [e, l2] = icalc(nextSize, nextLeft + 1, nextLeft + nextMid + 2);
                minR = Math.min(minR, e);
                maxR = Math.max(maxR, l2);
            }
        }
        const res: [number, number] = [minR, maxR];
        memo.set(key, res);
        return res;
    };

    const [earliest, latest] = icalc(n, a, b);
